// Pure text work: a line diff, unified hunks, and a reader for `git diff` output.
// Nothing here touches `$`, so every function is unit-tested on its own.

/** One line of an edit script: kept (' '), removed ('-') or added ('+'). */
export type Op = { type: ' ' | '-' | '+'; text: string }

/** One unified-diff hunk; `lines` carry their ' ', '-', '+' or '\' prefix. */
export type Hunk = {
  oldStart: number
  oldLines: number
  newStart: number
  newLines: number
  lines: string[]
}

/** Above this many LCS cells the changed middle is shown as one block. */
const MAX_CELLS = 4_000_000

/** A text as lines; a final newline does not make an empty last line. */
export function splitLines(text: string): string[] {
  if (text === '') return []
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * The shortest edit script from `a` to `b` by longest common subsequence.
 * Common head and tail are trimmed first (most edits are local), and a middle
 * too large to compare is reported as removed-then-added: counts stay exact
 * for that block, only the pairing is coarser.
 */
export function diffLines(a: readonly string[], b: readonly string[], maxCells = MAX_CELLS): Op[] {
  let head = 0
  while (head < a.length && head < b.length && a[head] === b[head]) head++
  let tail = 0
  while (
    tail < a.length - head &&
    tail < b.length - head &&
    a[a.length - 1 - tail] === b[b.length - 1 - tail]
  ) {
    tail++
  }
  const ops: Op[] = a.slice(0, head).map(text => ({ type: ' ', text }))
  const x = a.slice(head, a.length - tail)
  const y = b.slice(head, b.length - tail)
  const n = x.length
  const m = y.length

  if (n === 0 || m === 0 || (n + 1) * (m + 1) > maxCells) {
    for (const text of x) ops.push({ type: '-', text })
    for (const text of y) ops.push({ type: '+', text })
  } else {
    // dp[i][j] = LCS length of x[i..] and y[j..]; Uint16 holds it since min(n, m) < 2000 here.
    const w = m + 1
    const dp = new Uint16Array((n + 1) * w)
    for (let i = n - 1; i >= 0; i--) {
      for (let j = m - 1; j >= 0; j--) {
        dp[i * w + j] =
          x[i] === y[j]
            ? (dp[(i + 1) * w + j + 1] ?? 0) + 1
            : Math.max(dp[(i + 1) * w + j] ?? 0, dp[i * w + j + 1] ?? 0)
      }
    }
    let i = 0
    let j = 0
    while (i < n && j < m) {
      if (x[i] === y[j]) {
        ops.push({ type: ' ', text: x[i] ?? '' })
        i++
        j++
      } else if ((dp[(i + 1) * w + j] ?? 0) >= (dp[i * w + j + 1] ?? 0)) {
        ops.push({ type: '-', text: x[i] ?? '' })
        i++
      } else {
        ops.push({ type: '+', text: y[j] ?? '' })
        j++
      }
    }
    for (; i < n; i++) ops.push({ type: '-', text: x[i] ?? '' })
    for (; j < m; j++) ops.push({ type: '+', text: y[j] ?? '' })
  }
  for (const text of a.slice(a.length - tail)) ops.push({ type: ' ', text })
  return ops
}

/** Groups an edit script into hunks with `context` kept lines around each change. */
export function toHunks(ops: readonly Op[], context = 3): Hunk[] {
  const hunks: Hunk[] = []
  const changed = ops.flatMap((op, index) => (op.type === ' ' ? [] : [index]))
  if (changed.length === 0) return hunks

  // Old and new line counts consumed before each op, for the @@ numbers.
  const oldBefore: number[] = []
  const newBefore: number[] = []
  let o = 0
  let n = 0
  for (const op of ops) {
    oldBefore.push(o)
    newBefore.push(n)
    if (op.type !== '+') o++
    if (op.type !== '-') n++
  }

  let k = 0
  while (k < changed.length) {
    const first = changed[k] ?? 0
    let last = first
    // Merge changes whose context windows touch.
    while (k + 1 < changed.length && (changed[k + 1] ?? 0) - last <= context * 2 + 1) {
      k++
      last = changed[k] ?? last
    }
    k++
    const from = Math.max(0, first - context)
    const to = Math.min(ops.length - 1, last + context)
    const slice = ops.slice(from, to + 1)
    const oldLines = slice.filter(op => op.type !== '+').length
    const newLines = slice.filter(op => op.type !== '-').length
    const oldAt = oldBefore[from] ?? 0
    const newAt = newBefore[from] ?? 0
    hunks.push({
      // Unified diff numbers an empty side by the line before it.
      oldStart: oldLines > 0 ? oldAt + 1 : oldAt,
      oldLines,
      newStart: newLines > 0 ? newAt + 1 : newAt,
      newLines,
      lines: slice.map(op => op.type + op.text),
    })
  }
  return hunks
}

/** Lines added and removed across hunks. */
export function countHunks(hunks: readonly Hunk[]): { added: number; removed: number } {
  let added = 0
  let removed = 0
  for (const hunk of hunks) {
    for (const line of hunk.lines) {
      if (line.startsWith('+')) added++
      else if (line.startsWith('-')) removed++
    }
  }
  return { added, removed }
}

/**
 * The hunks as unified-diff text, at most `maxLines` diff lines. Whole hunks
 * are kept while they fit; a first hunk too long alone is cut and its header
 * recounted, so the text always parses as hunks.
 */
export function hunksText(
  hunks: readonly Hunk[],
  maxLines = Infinity,
): { text: string; shown: number; total: number } {
  const total = hunks.reduce((sum, hunk) => sum + hunk.lines.length, 0)
  const parts: string[] = []
  let shown = 0
  for (const hunk of hunks) {
    if (shown + hunk.lines.length <= maxLines) {
      parts.push(header(hunk), ...hunk.lines)
      shown += hunk.lines.length
      continue
    }
    if (shown === 0) {
      const lines = hunk.lines.slice(0, Math.max(1, maxLines))
      const cut = {
        ...hunk,
        oldLines: lines.filter(line => line[0] === ' ' || line[0] === '-').length,
        newLines: lines.filter(line => line[0] === ' ' || line[0] === '+').length,
        lines,
      }
      parts.push(header(cut), ...lines)
      shown = lines.length
    }
    break
  }
  return { text: parts.map(clean).join('\n'), shown, total }
}

function header(hunk: Hunk): string {
  return `@@ -${hunk.oldStart},${hunk.oldLines} +${hunk.newStart},${hunk.newLines} @@`
}

// ANSI escape sequences (CSI, OSC, and the one-byte C1 CSI), dropped whole.
// eslint-disable-next-line no-control-regex
const ANSI = /\u001b\[[0-?]*[ -/]*[@-~]|\u001b\][^\u0007\u001b]*(?:\u0007|\u001b\\)?|\u009b[0-?]*[ -/]*[@-~]/g
// C0 but tab and newline, DEL, and C1 (U+0080..U+009F, what stray binary bytes decode to).
// eslint-disable-next-line no-control-regex
const CONTROLS = /[\u0000-\u0008\u000b-\u001f\u007f-\u009f]/g

/**
 * Text safe to draw: a surface takes tab and newline as its only control
 * characters and refuses a whole tree holding any other. ANSI sequences go,
 * a line's trailing CR goes, and every other control becomes U+FFFD.
 */
export function clean(text: string): string {
  return text.replace(/\r$/, '').replace(ANSI, '').replace(CONTROLS, '\uFFFD')
}

/**
 * A name drawn on one line (a file path, a rename target, a prompt excerpt):
 * as `clean`, and a tab or newline in it becomes U+FFFD too. Paths may hold
 * any byte but NUL and `/`, so every path is untrusted text.
 */
export function cleanName(text: string): string {
  return clean(text).replace(/[\t\n\r]/g, '\uFFFD')
}

/** Git's own test for binary content: a NUL in the first 8000 characters. */
export function isBinary(text: string): boolean {
  return text.slice(0, 8000).includes('\0')
}

/** One file's section of `git diff` output. */
export type FileDiff = {
  /** Path before the change; null for an added file. */
  oldPath: string | null
  /** Path after the change; null for a deleted file. */
  newPath: string | null
  binary: boolean
  hunks: Hunk[]
  /** The section's text, to tell a changed section from an unchanged one. */
  raw: string
}

/**
 * Reads `git diff` output run with `--src-prefix=a/ --dst-prefix=b/`. Hunk
 * bodies are consumed by their @@ counts, so a content line can never be
 * mistaken for a header.
 */
export function parseGitDiff(text: string): FileDiff[] {
  const files: FileDiff[] = []
  const lines = splitLines(text)
  let file: (FileDiff & { rawLines: string[]; gitHeader: string }) | null = null
  let hunk: Hunk | null = null
  let oldLeft = 0
  let newLeft = 0

  const finish = () => {
    if (file === null) return
    if (file.oldPath === null && file.newPath === null) {
      // No ---/+++ or rename lines (a mode change, an empty new file): the
      // header names the same path twice, `a/<p> b/<p>`.
      const rest = file.gitHeader
      const path = unquote(rest.slice(2, 2 + Math.max(0, (rest.length - 5) / 2)))
      file.oldPath = file.rawLines.some(line => line.startsWith('new file mode')) ? null : path
      file.newPath = file.rawLines.some(line => line.startsWith('deleted file mode')) ? null : path
    }
    const { rawLines, gitHeader, ...section } = file
    files.push({ ...section, raw: rawLines.join('\n') })
    file = null
  }

  for (const line of lines) {
    if (hunk !== null && (oldLeft > 0 || newLeft > 0)) {
      hunk.lines.push(line)
      file?.rawLines.push(line)
      if (line.startsWith(' ')) {
        oldLeft--
        newLeft--
      } else if (line.startsWith('-')) oldLeft--
      else if (line.startsWith('+')) newLeft--
      else if (line === '') {
        // Some tools strip the space of an empty context line.
        hunk.lines[hunk.lines.length - 1] = ' '
        oldLeft--
        newLeft--
      }
      continue
    }
    if (line.startsWith('\\') && hunk !== null) {
      hunk.lines.push(line)
      file?.rawLines.push(line)
      continue
    }
    if (line.startsWith('diff --git ')) {
      finish()
      hunk = null
      file = {
        oldPath: null,
        newPath: null,
        binary: false,
        hunks: [],
        raw: '',
        rawLines: [line],
        gitHeader: line.slice('diff --git '.length),
      }
      continue
    }
    if (file === null) continue
    file.rawLines.push(line)
    const at = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/.exec(line)
    if (at) {
      hunk = {
        oldStart: Number(at[1]),
        oldLines: at[2] === undefined ? 1 : Number(at[2]),
        newStart: Number(at[3]),
        newLines: at[4] === undefined ? 1 : Number(at[4]),
        lines: [],
      }
      oldLeft = hunk.oldLines
      newLeft = hunk.newLines
      file.hunks.push(hunk)
    } else if (line.startsWith('rename from ')) file.oldPath = unquote(line.slice(12))
    else if (line.startsWith('rename to ')) file.newPath = unquote(line.slice(10))
    else if (line.startsWith('--- ')) file.oldPath = sidePath(line.slice(4), 'a/')
    else if (line.startsWith('+++ ')) file.newPath = sidePath(line.slice(4), 'b/')
    else if (line.startsWith('Binary files ')) {
      file.binary = true
      const names = /^Binary files (.+) and (.+) differ$/.exec(line)
      if (names) {
        file.oldPath = sidePath(names[1] ?? '', 'a/')
        file.newPath = sidePath(names[2] ?? '', 'b/')
      }
    }
  }
  finish()
  return files
}

/** A `---`/`+++` path: /dev/null is none; the prefix and git's trailing tab go. */
function sidePath(spec: string, prefix: string): string | null {
  const path = unquote(spec.replace(/\t$/, ''))
  if (path === '/dev/null') return null
  return path.startsWith(prefix) ? path.slice(prefix.length) : path
}

/** Undoes git's C-style quoting of an unusual path (`"a/we\tird"`). */
export function unquote(spec: string): string {
  if (!(spec.length >= 2 && spec.startsWith('"') && spec.endsWith('"'))) return spec
  const body = spec.slice(1, -1)
  const bytes: number[] = []
  const encoder = new TextEncoder()
  const simple: Record<string, string> = { n: '\n', t: '\t', r: '\r', '"': '"', '\\': '\\', a: '\x07', b: '\b', f: '\f', v: '\v' }
  for (let i = 0; i < body.length; i++) {
    const char = body[i] ?? ''
    if (char !== '\\') {
      bytes.push(...encoder.encode(char))
      continue
    }
    const next = body[i + 1] ?? ''
    const octal = /^[0-7]{3}/.exec(body.slice(i + 1))
    if (octal) {
      bytes.push(parseInt(octal[0], 8))
      i += 3
    } else {
      bytes.push(...encoder.encode(simple[next] ?? next))
      i += 1
    }
  }
  return new TextDecoder().decode(new Uint8Array(bytes))
}

/**
 * Applies hunks made against `base` and returns the result. Exact bytes
 * matter only for hashing, so a final newline is tracked from the
 * `\ No newline at end of file` markers.
 */
export function applyHunks(base: string, hunks: readonly Hunk[]): string {
  const from = splitLines(base)
  const out: string[] = []
  let at = 0
  let endsWithNewline = base === '' || base.endsWith('\n')
  for (const hunk of hunks) {
    const start = Math.max(0, hunk.oldLines > 0 ? hunk.oldStart - 1 : hunk.oldStart)
    while (at < start && at < from.length) out.push(from[at++] ?? '')
    let previous = ' '
    for (const line of hunk.lines) {
      const mark = line[0] ?? ' '
      if (mark === '\\') {
        // The marker speaks for the line before it: a new-side line means the
        // result ends without a newline; an old-side one that it now has one.
        endsWithNewline = previous === '-'
        continue
      }
      previous = mark
      if (mark === '+') out.push(line.slice(1))
      else if (mark === '-') at++
      else {
        out.push(line.slice(1))
        at++
      }
    }
  }
  while (at < from.length) out.push(from[at++] ?? '')
  if (out.length === 0) return ''
  return out.join('\n') + (endsWithNewline ? '\n' : '')
}

files.hooks/shell.ts:
// What a shell command changed, from git snapshots taken before and after it.
//
// Every git call here is read-only plumbing, run with --no-optional-locks:
// rev-parse, diff-index, ls-files, hash-object (without -w), show, cat-file,
// and diff --no-index for an untracked file. Porcelain `git diff <commit>`
// is avoided on purpose: it refreshes and rewrites .git/index (taking
// index.lock) whenever files are stat-dirty. Nothing is staged or written.

import type { PlayByPlayStep } from '../types'
import { applyHunks, isBinary, parseGitDiff, type FileDiff } from './diff'
import { bareStep, binaryNote, stepFromTexts } from './steps'

/** `$.process.run`'s shape, narrowed to what is read here (a test can fake it). */
export type Run = (
  argv: readonly string[],
  init?: { cwd?: string; stdin?: string },
) => Promise<{ exitCode: number; stdout: string; isStdoutTruncated: boolean }>

/** Git's empty tree: the base in a repository with no commit yet. */
export const EMPTY_TREE = '4b825dc642cb6eb9a060e54bf8d69288fbee4904'
/** Changed files looked at per command; past it one "more" step stands in. */
export const MAX_SHELL_FILES = 25
/** Above this many untracked files their contents are not hashed. */
const MAX_HASHED = 500

/** Output options shared by diff-index and diff --no-index, so both parse alike. */
const DIFF = [
  '--no-color',
  '--no-ext-diff',
  '--no-textconv',
  '--no-relative',
  '--src-prefix=a/',
  '--dst-prefix=b/',
  '-M',
  '--ignore-submodules',
]

/** The working tree as git sees it, against a fixed base commit. */
export type Snapshot = {
  root: string
  /** The session folder's place in the repository (`src/`), '' at its root. */
  prefix: string
  /** HEAD when the command started, kept for the after-snapshot so a commit
   * made by the command does not hide what it changed. */
  base: string
  files: FileDiff[]
  /** Untracked, unignored paths and their blob hash (null: not hashed). */
  untracked: Map<string, string | null>
}

function git(run: Run, root: string, args: readonly string[], stdin?: string) {
  return run(['git', '--no-optional-locks', '-c', 'core.quotepath=off', ...args], {
    cwd: root,
    ...(stdin !== undefined ? { stdin } : {}),
  })
}

/** Why there is no snapshot: not in a repository, or more pending than can be read whole. */
export type NoSnapshot = 'not-a-repo' | 'too-large'

/**
 * Snapshots the repository the session runs in, in two or three git calls
 * (three or four the first time, to find the repository). `at` reuses a
 * first snapshot's root and base, so the two compare like for like.
 */
export async function snapshot(
  run: Run,
  at?: Pick<Snapshot, 'root' | 'prefix' | 'base'>,
): Promise<Snapshot | NoSnapshot> {
  let where = at
  if (where === undefined) {
    // One call: root, prefix and HEAD. With no commit yet git fails on HEAD
    // but still prints the first two; outside a repository it prints nothing.
    const top = await run(['git', '--no-optional-locks', 'rev-parse', '--show-toplevel', '--show-prefix', 'HEAD'])
    const [root = '', prefix = '', head = ''] = top.stdout.split('\n')
    if (root === '') return 'not-a-repo'
    where = { root, prefix, base: top.exitCode === 0 && /^[0-9a-f]{40,64}$/.test(head) ? head : EMPTY_TREE }
  }
  const diff = await git(run, where.root, ['diff-index', '-p', ...DIFF, where.base, '--'])
  if (diff.isStdoutTruncated) return 'too-large'
  if (diff.exitCode !== 0) return 'not-a-repo'
  const listed = await git(run, where.root, ['ls-files', '--others', '--exclude-standard', '-z'])
  if (listed.isStdoutTruncated) return 'too-large'
  if (listed.exitCode !== 0) return 'not-a-repo'
  const paths = listed.stdout.split('\0').filter(path => path !== '')
  const untracked = new Map<string, string | null>(paths.map(path => [path, null]))
  if (paths.length > 0 && paths.length <= MAX_HASHED && !paths.some(path => path.includes('\n'))) {
    const hashed = await git(
      run,
      where.root,
      ['hash-object', '--no-filters', '--stdin-paths'],
      `${paths.join('\n')}\n`,
    )
    const hashes = hashed.stdout.split('\n').filter(line => line !== '')
    if (hashed.exitCode === 0 && hashes.length === paths.length) {
      paths.forEach((path, index) => untracked.set(path, hashes[index] ?? null))
    }
  }
  return { ...where, files: parseGitDiff(diff.stdout), untracked }
}

/** Git's blob id for a text: the hash `git hash-object` prints for its bytes. */
export async function blobHash(text: string): Promise<string> {
  const body = new TextEncoder().encode(text)
  const head = new TextEncoder().encode(`blob ${body.length}\0`)
  const all = new Uint8Array(head.length + body.length)
  all.set(head)
  all.set(body, head.length)
  const digest = await crypto.subtle.digest('SHA-1', all)
  return [...new Uint8Array(digest)].map(byte => byte.toString(16).padStart(2, '0')).join('')
}

/** What a path held in a snapshot. */
type State =
  | { kind: 'text'; text: string }
  | { kind: 'absent' }
  | { kind: 'binary'; bytes?: number | null; hash?: string | null }
  | { kind: 'untracked'; hash: string | null }
  | { kind: 'unknown' }

export type ShellOptions = {
  /** The path as steps show it, from a repository-relative one. */
  display: (path: string) => string
  /** The last text a file tool gave a file, by shown path (to diff an untracked file). */
  known: (file: string) => string | undefined
}

/** The steps a command made, comparing the snapshots taken around it. */
export async function shellSteps(
  run: Run,
  before: Snapshot,
  after: Snapshot,
  options: ShellOptions,
): Promise<PlayByPlayStep[]> {
  // Base contents, read once each per command: the text, a binary file (and
  // its size), null when the base has no such path, undefined when unreadable.
  type Base = string | { binary: number | null; hash: string | null } | null | undefined
  const baseTexts = new Map<string, Promise<Base>>()
  const readBase = async (path: string): Promise<Base> => {
    const spec = `${before.base}:${path}`
    // `--` makes git read `spec` as a revision only, never a glob pathspec
    // (`app/[slug]/page.tsx` would otherwise answer an empty file).
    const shown = await git(run, before.root, ['show', spec, '--'])
    if (shown.exitCode !== 0) return null
    if (shown.isStdoutTruncated || isBinary(shown.stdout)) {
      if (!isBinary(shown.stdout)) return undefined
      // One call for its blob id and size: "<id> blob <size>".
      const check = await git(run, before.root, ['cat-file', '--batch-check'], `${spec}\n`)
      const [hash = '', type = '', size = ''] = check.stdout.trim().split(' ')
      const ok = check.exitCode === 0 && type === 'blob'
      return { binary: ok && /^\d+$/.test(size) ? Number(size) : null, hash: ok ? hash : null }
    }
    return shown.stdout
  }
  const base = (path: string) => {
    let text = baseTexts.get(path)
    if (text === undefined) {
      text = readBase(path)
      baseTexts.set(path, text)
    }
    return text
  }
  const fromBase = (read: Base, absent: State): State =>
    read === undefined
      ? { kind: 'unknown' }
      : read === null
        ? absent
        : typeof read === 'string'
          ? { kind: 'text', text: read }
          : { kind: 'binary', bytes: read.binary, hash: read.hash }

  const stateOf = async (snap: Snapshot, path: string): Promise<State> => {
    const entry = snap.files.find(file => file.newPath === path)
    if (entry !== undefined) {
      if (entry.binary) return { kind: 'binary' }
      const from = entry.oldPath === null ? '' : await base(entry.oldPath)
      if (typeof from === 'string') return { kind: 'text', text: applyHunks(from, entry.hunks) }
      return from !== null && from !== undefined ? { kind: 'binary' } : { kind: 'unknown' }
    }
    if (snap.files.some(file => file.oldPath === path)) return { kind: 'absent' }
    if (snap.untracked.has(path)) return { kind: 'untracked', hash: snap.untracked.get(path) ?? null }
    return fromBase(await base(path), { kind: 'absent' })
  }

  // An untracked file had no earlier copy in git; a file tool may have left
  // us one, trusted only when its hash matches what was on disk.
  const earlier = async (path: string, hash: string | null): Promise<State> => {
    const text = options.known(options.display(path))
    if (text !== undefined && hash !== null && (await blobHash(text)) === hash) return { kind: 'text', text }
    return { kind: 'untracked', hash }
  }

  // An untracked file now on disk, read through git so no file is opened here.
  const current = async (path: string): Promise<State> => {
    const shown = await git(run, after.root, ['diff', ...DIFF.filter(arg => arg !== '-M'), '--no-index', '--', '/dev/null', path])
    if (shown.exitCode > 1 || shown.isStdoutTruncated) return { kind: 'unknown' }
    const [file] = parseGitDiff(shown.stdout)
    if (file?.binary) return { kind: 'binary' }
    return { kind: 'text', text: applyHunks('', file?.hunks ?? []) }
  }

  // Paths whose section of the diff changed, or whose untracked file did.
  const candidates = new Set<string>()
  const beforeRaw = new Set(before.files.map(file => file.raw))
  const afterRaw = new Set(after.files.map(file => file.raw))
  const touch = (file: FileDiff) => {
    if (file.oldPath !== null) candidates.add(file.oldPath)
    if (file.newPath !== null) candidates.add(file.newPath)
  }
  for (const file of after.files) if (!beforeRaw.has(file.raw)) touch(file)
  for (const file of before.files) if (!afterRaw.has(file.raw)) touch(file)
  const untracked = [...new Set([...before.untracked.keys(), ...after.untracked.keys()])].sort()
  for (const path of untracked) {
    const was = before.untracked.get(path)
    const now = after.untracked.get(path)
    if (before.untracked.has(path) !== after.untracked.has(path) || (was !== null && now !== null && was !== now)) {
      candidates.add(path)
    }
  }

  type Change = { path: string; was: State; now: State }
  const changes: Change[] = []
  const paths = [...candidates]
  for (const path of paths.slice(0, MAX_SHELL_FILES)) {
    let was = await stateOf(before, path)
    let now = await stateOf(after, path)
    if (was.kind === 'untracked') was = await earlier(path, was.hash)
    if (now.kind === 'untracked') now = await current(path)
    // Untracked before and after: git's own hashes settle it.
    const wasHash = before.untracked.get(path)
    const nowHash = after.untracked.get(path)
    const rehashed = wasHash != null && nowHash != null && wasHash !== nowHash
    if (!rehashed && !(await differs(was, now))) continue
    changes.push({ path, was, now })
  }

  // Pair a removed path with an added one into a rename: git's own pairing
  // first (a staged `git mv`), then identical content (a plain `mv`).
  const renames = new Map<string, string>() // new path -> old path
  const renamedAway = new Set<string>()
  const pair = (to: string, from: string) => {
    renames.set(to, from)
    renamedAway.add(from)
  }
  const isGone = (change: Change) => change.now.kind === 'absent' && change.was.kind !== 'absent'
  for (const file of after.files) {
    const { oldPath, newPath } = file
    if (oldPath === null || newPath === null || oldPath === newPath) continue
    const gone = changes.find(change => change.path === oldPath)
    const made = changes.find(change => change.path === newPath)
    // git paired them itself (a staged `git mv`), binary files included.
    if (gone && made && isGone(gone) && made.was.kind === 'absent' && made.now.kind !== 'absent') pair(newPath, oldPath)
  }
  for (const gone of changes) {
    if (!isGone(gone) || renamedAway.has(gone.path)) continue
    const wasText = gone.was.kind === 'text' ? gone.was.text : undefined
    const wasHash = gone.was.kind === 'untracked' || gone.was.kind === 'binary' ? (gone.was.hash ?? null) : null
    if (wasText === undefined && wasHash === null) continue
    for (const made of changes) {
      const { now } = made
      if (made.was.kind !== 'absent' || (now.kind !== 'text' && now.kind !== 'binary') || renames.has(made.path)) continue
      // Bytes are best compared by git's own hashes (a binary or untracked file).
      const madeHash = after.untracked.get(made.path) ?? (now.kind === 'text' ? await blobHash(now.text) : null)
      const same = wasText !== undefined ? now.kind === 'text' && now.text === wasText : madeHash === wasHash
      if (same) {
        pair(made.path, gone.path)
        break
      }
    }
  }

  const steps: PlayByPlayStep[] = []
  for (const { path, was, now } of changes) {
    if (renamedAway.has(path)) continue
    const file = options.display(path)
    const from = renames.get(path)
    if (from !== undefined) {
      const old = changes.find(change => change.path === from)
      if (now.kind !== 'text' || (old?.was.kind !== 'text' && old?.was.kind !== 'untracked')) {
        // A moved binary file: no lines to show.
        const bytes = old?.was.kind === 'binary' ? old.was.bytes : undefined
        steps.push({ ...bareStep(file, 'rename', 'shell', binaryNote(bytes)), from: options.display(from) })
        continue
      }
      // An untracked file moved whole has no earlier text; its hash matched.
      const oldText = old.was.kind === 'text' ? old.was.text : now.text
      const step = stepFromTexts(file, oldText, now.text, { via: 'shell', kind: 'rename', from: options.display(from) })
      if (step) steps.push(step)
      continue
    }
    const step = describe(file, was, now)
    if (step) steps.push(step)
  }
  if (paths.length > MAX_SHELL_FILES) {
    const left = paths.length - MAX_SHELL_FILES
    steps.push(bareStep(`${left} more file${left === 1 ? '' : 's'}`, 'more', 'shell', 'past the per-command cap; not compared'))
  }
  return steps
}

/** Whether two states of a path differ, leaning to "same" where git cannot tell. */
async function differs(was: State, now: State): Promise<boolean> {
  if (was.kind === 'text' && now.kind === 'text') return was.text !== now.text
  if (was.kind === 'absent' && now.kind === 'absent') return false
  if (was.kind === 'untracked') {
    if (now.kind === 'absent') return true
    // `git add` of a file the command did not change: same hash, no step.
    if (now.kind === 'text') return was.hash !== null && (await blobHash(now.text)) !== was.hash
    return false
  }
  return true
}

/** One path's change as a step. */
function describe(file: string, was: State, now: State): PlayByPlayStep | null {
  const textOf = (state: State) => (state.kind === 'text' ? state.text : null)
  if ((was.kind === 'text' || was.kind === 'absent') && (now.kind === 'text' || now.kind === 'absent')) {
    return stepFromTexts(file, textOf(was), textOf(now), { via: 'shell' })
  }
  if (was.kind === 'untracked') {
    return now.kind === 'absent'
      ? bareStep(file, 'delete', 'shell', 'deleted; it was untracked, so git kept no copy to show')
      : bareStep(file, 'change', 'shell', 'changed; it was untracked, so git kept no earlier copy to compare')
  }
  if (was.kind === 'binary' || now.kind === 'binary') {
    const kind = was.kind === 'absent' ? 'create' : now.kind === 'absent' ? 'delete' : 'change'
    const bytes = now.kind === 'binary' ? now.bytes : was.kind === 'binary' ? was.bytes : undefined
    return bareStep(file, kind, 'shell', binaryNote(bytes))
  }
  return bareStep(file, 'change', 'shell', 'changed; too large to compare')
}

files.hooks/steps.ts:
// Pure step logic: turning a tool call or a before/after pair into a step,
// the turn's scoreboard, and moving through steps. No `$` here.

import type { PlayByPlayKind, PlayByPlayStep, PlayByPlayTurn, PlayByPlayView } from '../types'
import { countHunks, diffLines, hunksText, isBinary, splitLines, toHunks } from './diff'

/** Diff lines kept per step for drawing; counts always cover the whole change. */
export const MAX_STEP_LINES = 400
/** Diff text kept per turn; later steps keep their counts and drop the lines. */
export const MAX_TURN_CHARS = 300_000
/** Steps kept per turn; past it they are counted in `dropped`. */
export const MAX_TURN_STEPS = 500
/** Turns kept for /replay <n>. */
export const MAX_TURNS = 10

/** A step from the text a file had before and after (null: it did not exist). */
export function stepFromTexts(
  file: string,
  before: string | null,
  after: string | null,
  options: { via: 'tool' | 'shell'; kind?: PlayByPlayKind; from?: string; note?: string },
): PlayByPlayStep | null {
  const kind =
    options.kind ?? (before === null ? 'create' : after === null ? 'delete' : 'edit')
  if (isBinary(before ?? '') || isBinary(after ?? '')) {
    // Never diff bytes as lines: they decode to control characters.
    if (before === after) return null
    const bytes = new TextEncoder().encode(after ?? before ?? '').length
    const step = bareStep(file, kind === 'edit' || kind === 'write' ? 'change' : kind, options.via, binaryNote(bytes))
    return options.from !== undefined ? { ...step, from: options.from } : step
  }
  const ops = diffLines(splitLines(before ?? ''), splitLines(after ?? ''))
  const hunks = toHunks(ops)
  // A step that changes nothing (a no-op write, a final newline alone) is
  // only worth keeping when it says something: a rename, or a new empty file.
  if (hunks.length === 0 && kind !== 'rename' && kind !== 'create' && kind !== 'delete') return null
  const { added, removed } = countHunks(hunks)
  const { text, shown, total } = hunksText(hunks, MAX_STEP_LINES)
  const cut = shown < total ? `showing ${shown} of ${total} diff lines` : undefined
  const note = [options.note, cut].filter(Boolean).join('; ') || undefined
  return {
    file,
    ...(options.from !== undefined ? { from: options.from } : {}),
    kind,
    via: options.via,
    added,
    removed,
    hunks: text,
    ...(note ? { note } : {}),
  }
}

/** The note a binary step shows: `binary file changed (1234 bytes)`. */
export function binaryNote(bytes?: number | null): string {
  return bytes === undefined || bytes === null ? 'binary file changed' : `binary file changed (${bytes} bytes)`
}

/** A step with no line detail (binary, or no earlier copy to compare). */
export function bareStep(
  file: string,
  kind: PlayByPlayKind,
  via: 'tool' | 'shell',
  note: string,
  counts: { added?: number; removed?: number } = {},
): PlayByPlayStep {
  return { file, kind, via, added: counts.added ?? 0, removed: counts.removed ?? 0, hunks: '', note }
}

/** Reads a string field off a value of unknown shape. */
export function field(value: unknown, key: string): string | undefined {
  if (typeof value !== 'object' || value === null) return undefined
  const found = (value as Record<string, unknown>)[key]
  return typeof found === 'string' ? found : undefined
}

function flag(value: unknown, key: string): boolean {
  return typeof value === 'object' && value !== null && (value as Record<string, unknown>)[key] === true
}

/** Replaces `oldString` with `newString` once, or everywhere, as Edit does. */
export function applyEdit(text: string, oldString: string, newString: string, all: boolean): string {
  if (oldString === '') return newString
  if (all) return text.split(oldString).join(newString)
  const at = text.indexOf(oldString)
  return at < 0 ? text : text.slice(0, at) + newString + text.slice(at + oldString.length)
}

/** What an Edit call did, from its record when it has one, else from its input. */
export function editStep(
  file: string,
  input: { old_string: string; new_string: string; replace_all?: boolean },
  result: unknown,
): { step: PlayByPlayStep | null; after?: string } {
  if (flag(result, 'staged')) return { step: null }
  // The record says what was applied, the person's own changes included.
  const oldString = field(result, 'oldString') ?? input.old_string
  const newString = field(result, 'newString') ?? input.new_string
  const all =
    typeof result === 'object' && result !== null && 'replaceAll' in result
      ? flag(result, 'replaceAll')
      : input.replace_all === true
  if (typeof result === 'object' && result !== null && 'originalFile' in result) {
    const original = field(result, 'originalFile')
    if (original === undefined) {
      // originalFile null: Edit made a new file from an empty old_string.
      return { step: stepFromTexts(file, null, newString, { via: 'tool', kind: 'create' }), after: newString }
    }
    const after = applyEdit(original, oldString, newString, all)
    return { step: stepFromTexts(file, original, after, { via: 'tool', kind: 'edit' }), after }
  }
  // No record of the file (a hook above answered for the tool): show the
  // replaced text alone, numbered from 1.
  return {
    step: stepFromTexts(file, oldString, newString, {
      via: 'tool',
      kind: 'edit',
      note: 'line numbers are relative to the edit',
    }),
  }
}

/** What a Write call did. */
export function writeStep(
  file: string,
  input: { content: string },
  result: unknown,
): { step: PlayByPlayStep | null; after?: string } {
  if (flag(result, 'staged')) return { step: null }
  const content = field(result, 'content') ?? input.content
  const type = field(result, 'type')
  const original = field(result, 'originalFile')
  if (type === 'create') {
    return { step: stepFromTexts(file, null, content, { via: 'tool', kind: 'create' }), after: content }
  }
  if (original !== undefined) {
    return { step: stepFromTexts(file, original, content, { via: 'tool', kind: 'write' }), after: content }
  }
  const lines = splitLines(content).length
  return {
    step: bareStep(file, 'write', 'tool', 'rewritten whole; the earlier copy was too large to compare', {
      added: lines,
    }),
    after: content,
  }
}

/** What a NotebookEdit call did to its cell. */
export function cellStep(
  file: string,
  input: { new_source: string; edit_mode?: string; cell_id?: string },
  result: unknown,
): PlayByPlayStep | null {
  if (field(result, 'error')) return null
  const mode = field(result, 'edit_mode') ?? input.edit_mode ?? 'replace'
  const before = mode === 'insert' ? null : (field(result, 'old_source') ?? '')
  const after = mode === 'delete' ? null : (field(result, 'new_source') ?? input.new_source)
  const cell = field(result, 'cell_id') ?? input.cell_id
  const note = `${mode} cell${cell ? ` ${cell}` : ''}`
  return stepFromTexts(file, before, after, { via: 'tool', kind: 'cell', note })
}

/** A path relative to `cwd` when it lies inside it. */
export function relPath(path: string, cwd: string): string {
  const root = cwd.endsWith('/') ? cwd : `${cwd}/`
  return path.startsWith(root) ? path.slice(root.length) : path
}

/** Adds steps to a turn, keeping the per-turn caps. */
export function addSteps(turn: PlayByPlayTurn, steps: readonly PlayByPlayStep[]): PlayByPlayTurn {
  let chars = turn.steps.reduce((sum, step) => sum + step.hunks.length, 0)
  const kept = [...turn.steps]
  let dropped = turn.dropped
  for (const step of steps) {
    if (kept.length >= MAX_TURN_STEPS) {
      dropped++
      continue
    }
    if (chars + step.hunks.length > MAX_TURN_CHARS && step.hunks !== '') {
      const note = [step.note, 'lines dropped: this turn changed too much to keep them all']
        .filter(Boolean)
        .join('; ')
      kept.push({ ...step, hunks: '', note })
      continue
    }
    chars += step.hunks.length
    kept.push(step)
  }
  return { ...turn, steps: kept, dropped }
}

/** The files a turn touched, in order of first change, with that step's index. */
export function jumpList(turn: PlayByPlayTurn): { file: string; step: number }[] {
  const seen = new Map<string, number>()
  turn.steps.forEach((step, index) => {
    if (step.kind !== 'more' && !seen.has(step.file)) seen.set(step.file, index)
  })
  return [...seen].map(([file, step]) => ({ file, step }))
}

export type Score = {
  edits: number
  files: number
  added: number
  removed: number
  /** The file with the most lines changed, ties to the first touched. */
  biggest: { file: string; added: number; removed: number } | null
}

/** The scoreboard for a turn. */
export function score(turn: PlayByPlayTurn): Score {
  const perFile = new Map<string, { added: number; removed: number }>()
  let added = 0
  let removed = 0
  let edits = 0
  for (const step of turn.steps) {
    if (step.kind === 'more') continue
    edits++
    added += step.added
    removed += step.removed
    const total = perFile.get(step.file) ?? { added: 0, removed: 0 }
    perFile.set(step.file, { added: total.added + step.added, removed: total.removed + step.removed })
  }
  let biggest: Score['biggest'] = null
  for (const [file, total] of perFile) {
    if (biggest === null || total.added + total.removed > biggest.added + biggest.removed) {
      biggest = { file, ...total }
    }
  }
  return { edits: edits + turn.dropped, files: perFile.size, added, removed, biggest }
}

const plural = (count: number, word: string) => `${count} ${word}${count === 1 ? '' : 's'}`

/** `+38 −12`, with a real minus sign. */
export function plusMinus(added: number, removed: number): string {
  return `+${added} −${removed}`
}

/** `4 edits · 3 files · +38 −12`. */
export function summaryLine(turn: PlayByPlayTurn): string {
  const { edits, files, added, removed } = score(turn)
  return `${plural(edits, 'edit')} · ${plural(files, 'file')} · ${plusMinus(added, removed)}`
}

/** A movement through a turn's steps. */
export type Nav =
  | { go: 'next' }
  | { go: 'prev' }
  | { go: 'first' }
  | { go: 'last' }
  | { go: 'jump'; file: number }
  | { go: 'close' }

/** The step a movement lands on, kept inside the turn. */
export function navigate(view: PlayByPlayView, nav: Nav, turn: PlayByPlayTurn): PlayByPlayView {
  const last = Math.max(0, turn.steps.length - 1)
  const clamp = (step: number) => Math.min(last, Math.max(0, step))
  switch (nav.go) {
    case 'next':
      return { ...view, step: clamp(view.step + 1) }
    case 'prev':
      return { ...view, step: clamp(view.step - 1) }
    case 'first':
      return { ...view, step: 0 }
    case 'last':
      return { ...view, step: last }
    case 'jump': {
      const target = jumpList(turn)[nav.file - 1]
      return target === undefined ? view : { ...view, step: target.step }
    }
    case 'close':
      return view
  }
}

/** What a key does in the replay pane, or null for a key it ignores. */
export function keyAction(key: string): Nav | null {
  switch (key) {
    case 'right':
    case 'down':
    case 'n':
      return { go: 'next' }
    case 'left':
    case 'up':
    case 'p':
      return { go: 'prev' }
    case 'home':
      return { go: 'first' }
    case 'end':
      return { go: 'last' }
    case 'q':
      return { go: 'close' }
  }
  return /^[1-9]$/.test(key) ? { go: 'jump', file: Number(key) } : null
}

/** Parses `/replay [n]`: which kept turn, 1 being the latest. */
export function parseBack(args: string): number | null {
  const text = args.trim()
  if (text === '') return 1
  if (!/^\d+$/.test(text)) return null
  const back = Number(text)
  return back >= 1 && back <= MAX_TURNS ? back : null
}

/** The first `max` characters of a prompt, on one line. */
export function excerpt(text: string, max = 80): string {
  const line = text.replace(/\s+/g, ' ').trim()
  return line.length > max ? `${line.slice(0, max - 1)}…` : line
}

/** `src/a.ts`, `old.ts -> new.ts` for a rename. */
export function stepTitle(step: PlayByPlayStep): string {
  return step.from !== undefined ? `${step.from} -> ${step.file}` : step.file
}

